// Axon Shell — the user's accent colour (Axon Preferences > Appearance).
//
// stylesheet*.css carry the default blue. For another accent this loads a
// small override from accents/ (generated by scripts/gen_tokens.py: only the
// rules that use the accent or focus ring) and swaps it when the accent, the
// colour scheme or High Contrast changes.

import Gio from 'gi://Gio';
import St from 'gi://St';

import {accentStylesheet} from './ui-logic.js';

export default class AccentManager {
    constructor(extension) {
        this._extension = extension;
        this._file = null;
        this._ids = [];
        this._contextId = 0;
    }

    enable() {
        this._settings = this._extension.getSettings();
        this._interface = new Gio.Settings({schema_id: 'org.gnome.desktop.interface'});
        this._a11y = new Gio.Settings({schema_id: 'org.gnome.desktop.a11y.interface'});
        const apply = () => this._apply();
        this._ids = [
            [this._settings, this._settings.connect('changed::accent-color', apply)],
            [this._interface, this._interface.connect('changed::color-scheme', apply)],
            [this._a11y, this._a11y.connect('changed::high-contrast', apply)],
        ];
        // GNOME replaces the theme object when the Shell theme reloads, which
        // drops extra stylesheets: load ours again into the new one.
        this._context = St.ThemeContext.get_for_stage(global.stage);
        this._contextId = this._context.connect('changed', () => {
            this._file = null;
            this._apply();
        });
        this._apply();
    }

    disable() {
        this._unload();
        for (const [settings, id] of this._ids)
            settings.disconnect(id);
        this._ids = [];
        if (this._context && this._contextId)
            this._context.disconnect(this._contextId);
        this._context = null;
        this._contextId = 0;
        this._settings = null;
        this._interface = null;
        this._a11y = null;
    }

    _unload() {
        if (!this._file || !this._context)
            return;
        try {
            this._context.get_theme().unload_stylesheet(this._file);
        } catch (e) {
            console.warn('AxonShell: could not unload the accent stylesheet:', e.message);
        }
        this._file = null;
    }

    _apply() {
        this._unload();
        const relative = accentStylesheet(
            this._settings.get_string('accent-color'),
            this._interface.get_string('color-scheme'),
            this._a11y.get_boolean('high-contrast'));
        if (!relative)
            return;
        const file = this._extension.dir.resolve_relative_path(relative);
        try {
            this._context.get_theme().load_stylesheet(file);
            this._file = file;
        } catch (e) {
            console.warn('AxonShell: could not load the accent stylesheet:', e.message);
        }
    }
}
